Translate the following GNU C++17 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to translate:
<original_code>
#include<bits/stdc++.h>
#define pa pair<int,int>
#define CLR(a,x) memset(a,x,sizeof(a))
#define MP make_pair
#define fi first
#define se second
using namespace std;
typedef long long ll;
typedef unsigned long long ull;
typedef unsigned int ui;
typedef long double ld;
const int maxn=55,maxt=2*maxn,maxp=maxt*maxn,maxe=5*maxt*maxn*maxn;
const int inf=1e9;

inline char gc(){
	return getchar();
	static const int maxs=1<<16;static char buf[maxs],*p1=buf,*p2=buf;
    return p1==p2&&(p2=(p1=buf)+fread(buf,1,maxs,stdin),p1==p2)?EOF:*p1++;
}
inline ll rd(){
    ll x=0;char c=gc();bool neg=0;
    while(c<'0'||c>'9'){if(c=='-') neg=1;c=gc();}
    while(c>='0'&&c<='9') x=(x<<1)+(x<<3)+c-'0',c=gc();
    return neg?(~x+1):x;
}

struct Edge{
	int b,l,c,ne;
}eg[maxe];
int ect=1,egh[maxp];
int N,M,K,C,D,cnt[maxn];
int id[maxn][maxt],S=1,E=2,pct=2;
bool flag[maxp];
int dis[maxp],ans;
queue<int> q;


inline void adeg(int a,int b,int c,int l){
	eg[++ect].b=b,eg[ect].ne=egh[a],egh[a]=ect;
	eg[ect].c=c,eg[ect].l=l;
}

inline void ade(int a,int b,int c,int l){
	adeg(a,b,c,l),adeg(b,a,-c,0);
}

inline bool spfa(){
	for(int i=1;i<=pct;i++) flag[i]=0,dis[i]=inf;
	dis[S]=0;q.push(S);
	while(!q.empty()){
		int p=q.front();q.pop();
		flag[p]=0;
		for(int i=egh[p];i;i=eg[i].ne){
			if(!eg[i].l) continue;
			int b=eg[i].b;
			if(dis[b]>dis[p]+eg[i].c){
				dis[b]=dis[p]+eg[i].c;
				if(!flag[b]) q.push(b),flag[b]=1;
			}
		}
	}
	return dis[E]<inf;
}

int dinic(int x,int y){
	if(x==S) return y;
	flag[x]=1;
	int tmp=y;
	for(int i=egh[x];i;i=eg[i].ne){
		int b=eg[i].b;if(flag[b]||!eg[i^1].l||dis[x]<dis[b]+eg[i^1].c) continue;
		int re=dinic(b,min(tmp,eg[i^1].l));
		if(re){
			tmp-=re,eg[i^1].l-=re,eg[i].l+=re;
			if(!tmp) break;
		}
	}return y-tmp;
}

int main(){
    //freopen("","r",stdin);
    N=rd(),M=rd(),K=rd(),C=rd(),D=rd();
    for(int i=1;i<=K;i++) cnt[rd()]++;
    for(int i=1;i<=N;i++){
    	for(int j=1;j<=K+M+2;j++){
    		id[i][j]=++pct;
    		if(i==1) ade(id[i][j],E,C*(j-1),inf);
    		if(j>1) ade(id[i][j-1],id[i][j],0,inf);
    	}
    	if(cnt[i]) ade(S,id[i][1],0,cnt[i]);
    }
    for(int i=1;i<=M;i++){
    	int a=rd(),b=rd();
    	for(int j=1;j<=K+M+1;j++){
    		for(int k=1;k<=2*K-1;k+=2){
    			ade(id[a][j],id[b][j+1],k*D,1);
    			ade(id[b][j],id[a][j+1],k*D,1);
    		}
    	}
    }
    int nn=0;
    while(spfa()){
    	int aa=-1;
    	while(aa){
    		CLR(flag,0);
    		aa=dinic(E,inf);
    		nn+=aa,ans+=dis[E]*aa;
    	}
    }
    assert(nn==K);
	printf("%d\n",ans);
    return 0;
}
